# OpenAI-compatible servers hold no server-side session state, so we encode the full
# message history as JSON in the session_id field. 50 KB is a conservative safety net:
# it is well below typical LLM context windows and small enough that it does not bloat
# the HTTP response payload. Older turns are dropped first; the system message at index 0
# is always kept.
_MAX_SESSION_BYTES = 50 * 1024
_JSON_LIST_OVERHEAD_BYTES = 2
_JSON_LIST_SEPARATOR_BYTES = 2

_THINK_OPEN = "<think>"
_THINK_CLOSE = "</think>"


def _partial_tag_suffix(buf: str, tag: str) -> str:
    """Return the longest suffix of ``buf`` that is a proper prefix of ``tag``.

    This detects a tag that has only partially arrived at the end of a streaming
    buffer (e.g. ``"<th"`` for ``"<think>"``) so it can be held back and re-fed
    with the next chunk instead of being emitted or misinterpreted.
    """
    max_len = min(len(buf), len(tag) - 1)
    for length in range(max_len, 0, -1):
        if tag.startswith(buf[-length:]):
            return buf[-length:]
    return ""


def _strip_think_blocks(buf: str, in_think: bool) -> tuple[str, str, bool]:
    """Strip ``<think>...</think>`` spans from a streaming text buffer.

    Returns a 3-tuple ``(emit, remaining, new_in_think)`` where ``emit`` is the text
    safe to show users, ``remaining`` holds any partial open/close tag that must be
    re-fed with the next chunk, and ``new_in_think`` indicates whether the parser is
    inside a think block after processing ``buf``.
    """
    emit: list[str] = []
    while buf:
        if in_think:
            idx = buf.find(_THINK_CLOSE)
            if idx != -1:
                buf = buf[idx + len(_THINK_CLOSE) :]
                in_think = False
                continue
            # No full closing tag; hold back any partial closing tag at the end.
            return "".join(emit), _partial_tag_suffix(buf, _THINK_CLOSE), True
        else:
            idx = buf.find(_THINK_OPEN)
            if idx != -1:
                emit.append(buf[:idx])
                buf = buf[idx + len(_THINK_OPEN) :]
                in_think = True
                continue
            # No full opening tag; emit everything except a partial opening tag.
            partial = _partial_tag_suffix(buf, _THINK_OPEN)
            emit.append(buf[: len(buf) - len(partial)] if partial else buf)
            return "".join(emit), partial, False
    return "".join(emit), "", in_think


def _merge_tool_call_chunk(acc: list[dict[str, Any]], chunk: dict[str, Any]) -> None:
    """Merge a streaming OpenAI ``tool_calls`` delta into the accumulator ``acc``.

    Tool call deltas are identified by ``chunk["index"]``. The first chunk for an
    index seeds ``id`` and ``function.name``; every chunk appends
    ``function.arguments`` so the full argument string is reconstructed. Parallel
    tool calls at distinct indexes are tracked independently.
    """
    index = chunk.get("index", 0)
    entry = next((e for e in acc if e["index"] == index), None)
    if entry is None:
        function = chunk.get("function") or {}
        entry = {
            "index": index,
            "id": chunk.get("id"),
            "function": {"name": function.get("name"), "arguments": ""},
        }
        acc.append(entry)
    else:
        if entry.get("id") is None and chunk.get("id"):
            entry["id"] = chunk["id"]
        function = chunk.get("function") or {}
        if not entry["function"].get("name") and function.get("name"):
            entry["function"]["name"] = function["name"]

    if arguments := (chunk.get("function") or {}).get("arguments"):
        entry["function"]["arguments"] += arguments


def _message_size_bytes(message: dict[str, Any]) -> int:
    return len(json.dumps(message).encode())


def _trim_session(messages: list[dict[str, Any]]) -> list[dict[str, Any]]:
    message_sizes = [_message_size_bytes(message) for message in messages]
    total_size = _JSON_LIST_OVERHEAD_BYTES + sum(message_sizes)
    if len(message_sizes) > 1:
        total_size += (len(message_sizes) - 1) * _JSON_LIST_SEPARATOR_BYTES

    while total_size > _MAX_SESSION_BYTES and len(messages) > 2:
        messages.pop(1)
        total_size -= message_sizes.pop(1) + _JSON_LIST_SEPARATOR_BYTES
    return messages


class OpenAICompatibleProvider(AssistantProvider):
    """Provider for any server exposing an OpenAI-style POST /v1/chat/completions endpoint.

    The class is instantiated with preset-specific data so the same implementation can be
    registered multiple times for different presets (e.g. the MLflow AI Gateway).
    """

    def __init__(
        self,
        name: str,
        display_name: str,
        description: str,
        connection_hint: str,
        list_models_fn: Callable[[str | None, str | None], list[str]] | None = None,
        chat_url_builder: Callable[[str | None, str], str | None] | None = None,
        default_base_url: str | None = None,
        **kwargs: Any,
    ) -> None:
        self._name = name
        self._display_name = display_name
        self._description = description
        self._connection_hint = connection_hint
        self._list_models_fn = list_models_fn
        self._chat_url_builder = chat_url_builder
        self._default_base_url = default_base_url

    @property
    def name(self) -> str:
        return self._name

    @property
    def display_name(self) -> str:
        return self._display_name

    @property
    def description(self) -> str:
        return self._description

    def is_available(self) -> bool:
        return True

    def _load_config(self) -> ProviderConfig:
        try:
            return load_config(self.name)
        except RuntimeError:
            return ProviderConfig()

    def _resolve_base_url(self, base_url: str | None = None) -> str | None:
        if base_url:
            return base_url
        config = self._load_config()
        return config.base_url or self._default_base_url

    def list_models(
        self, base_url: str | None = None, api_key: str | None = None
    ) -> list[str]:
        if self._list_models_fn is None:
            raise NotImplementedError(
                f"Model listing is not supported for provider '{self.name}'"
            )
        return self._list_models_fn(self._resolve_base_url(base_url), api_key)

    def check_connection(self, echo: Callable[[str], None] | None = None) -> None:
        if self._list_models_fn is None:
            raise NotImplementedError(
                f"Connection for provider '{self.name}' is verified by the frontend"
            )
        if echo:
            echo(f"Connecting to {self.display_name}...")
        try:
            self.list_models()
        except ProviderNotConfiguredError:
            raise

